export const ALL_PROVIDER_IDS = Object.values(ProviderId) as ProviderId[];

export const AUTOREG_PROVIDERS = ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].hasAutoreg);

export const AI_PROXY_PROVIDERS = ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].isAiProxy);

export const PROVIDERS_BY_CATEGORY: Record<ProviderCategory, ProviderId[]> = {
  ide: ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].category === 'ide'),
  git: ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].category === 'git'),
  cloud: ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].category === 'cloud'),
  ai: ALL_PROVIDER_IDS.filter(id => PROVIDER_META[id].category === 'ai'),
};

export function isValidProviderId(id: string): id is ProviderId {
  return (ALL_PROVIDER_IDS as readonly string[]).includes(id);
}

const AUTOREG_PLUGIN_IDS = new Set(
  AUTOREG_PROVIDERS.map(id => `${id.replace(/_/g, '-')}-autoreg`),
);

export function isBundledProviderPlugin(pluginId: string): boolean {
  return AUTOREG_PLUGIN_IDS.has(pluginId);
}
